pub fn smallest_num(nums: &Vec<i32>) -> i32 {
    // Since the input vector is guaranteed non‐empty, it's safe to use the first element
    let mut min_value = nums[0];

    // Iterate over the rest of the elements and update min_value whenever we find a smaller one
    for &num in nums.iter().skip(1) {
        if num < min_value {
            min_value = num;
        }
    }

    min_value
}